      push('word', start, sl, sc, { name: normName(raw), colon: true });
      continue;
    }

    if (isLetter(c)) {
      while (i < n && isNameChar(source[i])) advance(1);
      const raw = source.slice(start, i);
      const name = normName(raw);
      if (name === 'ma' && source[i] === ':') {
