      advance(1);
      if (source[i] === '=' || source[i] === '>') advance(1);
      push('cmp', start, sl, sc);
      continue;
    }
    if (c === '>') {
      advance(1);
      if (source[i] === '=') advance(1);
      push('cmp', start, sl, sc);
      continue;
    }
    if (c === '=') { advance(1); push('cmp', start, sl, sc); continue; }

    const cp = source.codePointAt(i)!;
    const ch = String.fromCodePoint(cp);
