  | { k: 'if'; cond: Cond; body: Stmt[]; tok: Token }
  | { k: 'ifelse'; cond: Cond; body: Stmt[]; elseBody: Stmt[]; tok: Token }
  | { k: 'stop'; tok: Token }
  | { k: 'home'; tok: Token }
