    case 'neg':
      return -evaluate(e.e, scope);
    case 'bin': {
      const a = evaluate(e.a, scope);
      const b = evaluate(e.b, scope);
      switch (e.op) {
        case '+':
          return check(a + b);
        case '-':
          return check(a - b);
        case '*':
          return check(a * b);
        case '/':
          if (b === 0) throw new EvalFailure('div0');
          return check(a / b);
      }
    }
  }
}

