      reason: 'Kształt jest dobry, ale część odcinków ma inny kolor niż we wzorze.',
      segments: segs,
    };
  }

  const compiled = compile(source, c.mode);
  const program = compiled.program as Program;
  const unmet = (c.requires ?? []).filter((r) => !uses(program, r));
  if (unmet.length) {
    return {
      pass: false,
