input.content:
/* ------------------------------------------------------------------ base */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  scrollbar-color: var(--rule-strong) transparent;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: var(--t-md);
  line-height: 1.45;
  font-variant-numeric: lining-nums;
  min-height: 100dvh;
}

::selection {
  background: var(--selection);
}

a {
  color: inherit;
  text-underline-offset: 0.2em;
  text-decoration-thickness: 1px;
}

code,
kbd,
pre {
  font-family: var(--font-code);
  font-size: 0.92em;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  background: var(--sheet);
  color: var(--ink);
  padding: 8px 14px;
  border-radius: var(--r-ctl);
  box-shadow: var(--shadow-pop);
  font-weight: 600;
}
.skip-link:focus {
  top: 8px;
}

main:focus {
  outline: none;
}

/* chart lettering: condensed grotesque caps, as on a printed wall chart */
.band-title,
.section-title,
.ref-h2,
.task-title,
.brand-name {
  font-stretch: 68%;
  font-weight: 780;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1;
  text-wrap: balance;
}

/* ------------------------------------------------------------------ buttons */

.btn {
  --btn-h: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: var(--btn-h);
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: var(--r-ctl);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: var(--t-sm);
  font-weight: 650;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition:
    background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out),
    color var(--t-fast) var(--ease-out);
}
.btn .icon {
  flex: none;
}
.btn:disabled,
.btn[aria-disabled='true'] {
  opacity: 0.42;
  cursor: not-allowed;
}
.btn-sm {
  --btn-h: 30px;
  padding: 0 10px;
  font-size: var(--t-xs);
}
.btn-icon {
  width: var(--btn-h);
  padding: 0;
}
.btn-quiet {
  background: var(--sheet);
  border-color: var(--rule-strong);
}
.btn-quiet:hover:not(:disabled) {
  background: var(--sheet-2);
  border-color: var(--ink-3);
}
.btn-quiet:active:not(:disabled) {
  background: var(--rule);
}
.btn-primary {
  background: var(--mode-band);
  color: var(--on-band);
  padding: 0 16px;
}
.btn-primary:hover:not(:disabled) {
  background: color-mix(in oklab, var(--mode-band) 84%, #000);
}
.btn-primary:active:not(:disabled) {
  background: color-mix(in oklab, var(--mode-band) 72%, #000);
}
.btn-task {
  background: var(--band-task);
  color: var(--on-band);
  padding: 0 16px;
}
.btn-task:hover {
  background: color-mix(in oklab, var(--band-task) 84%, #000);
}
.btn-danger {
  color: var(--error);
  border-color: var(--error-rule);
}
.btn-danger:hover:not(:disabled) {
  background: var(--error-bg);
  border-color: var(--error);
}

/* ------------------------------------------------------------------ header */

.app-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: stretch;
  gap: var(--s-4);
  height: var(--header-h);
  padding: 0 var(--s-3) 0 var(--s-4);
  background: var(--header);
  color: var(--on-header);
  --brand-turtle: #4cc59c;
}
.app-header :focus-visible {
  outline-color: var(--on-header);
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--on-header);
  text-decoration: none;
  padding-right: var(--s-2);
}
.brand-mark {
  color: var(--on-header);
}
.brand-name {
  font-size: 1.375rem;
  letter-spacing: 0.04em;
}
.nav {
  display: flex;
  align-items: stretch;
}
.nav-link {
  display: flex;
  align-items: center;
  padding: 0 14px;
  color: var(--on-header-2);
  text-decoration: none;
  font-weight: 600;
  font-size: var(--t-sm);
  border-bottom: 3px solid transparent;
  padding-top: 3px;
  transition: color var(--t-fast) var(--ease-out);
}
.nav-link:hover {
  color: var(--on-header);
}
.nav-link[aria-current='page'] {
  color: var(--on-header);
}
.nav-link:nth-child(1)[aria-current='page'] {
  border-bottom-color: #4cc59c;
}
.nav-link:nth-child(2)[aria-current='page'] {
  border-bottom-color: #86b6ec;
}
.nav-link:nth-child(3)[aria-current='page'] {
  border-bottom-color: #e6a669;
}
.nav-link:nth-child(4)[aria-current='page'] {
  border-bottom-color: #cba8e6;
}
.nav-link:focus-visible {
  outline-offset: -4px;
}
.header-tools {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
}
.btn-header {
  color: var(--on-header-2);
}
.btn-header:hover {
  color: var(--on-header);
  background: rgb(255 255 255 / 0.08);
}

/* ------------------------------------------------------------------ studio */

.studio {
  --mode: var(--ink-2d);
  --mode-fill: var(--fill-2d);
  --mode-band: var(--band-2d);
  display: grid;
  grid-template-columns: minmax(400px, 36%) minmax(0, 1fr);
  height: calc(100dvh - var(--header-h));
  min-height: 560px;
}
.studio[data-mode='3d'] {
  --mode: var(--ink-3d);
  --mode-fill: var(--fill-3d);
  --mode-band: var(--band-3d);
}

.studio-code {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  background: var(--sheet);
  border-right: 1px solid var(--rule-strong);
}

.code-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  padding: 10px var(--s-3);
  border-bottom: 1px solid var(--rule);
}

.seg {
  display: inline-flex;
  padding: 2px;
  border: 1px solid var(--rule-strong);
  border-radius: 7px;
  background: var(--sheet-2);
}
.seg-btn {
  min-width: 56px;
  height: 30px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--ink-2);
  font: inherit;
  font-weight: 750;
  font-size: var(--t-sm);
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: background-color var(--t-fast) var(--ease-out), color var(--t-fast) var(--ease-out);
}
.seg-btn:hover:not(:disabled):not([aria-pressed='true']) {
  color: var(--ink);
  background: var(--rule);
}
.seg-btn[aria-pressed='true']:nth-child(1) {
  background: var(--band-2d);
  color: var(--on-band);
}
.seg-btn[aria-pressed='true']:nth-child(2) {
  background: var(--band-3d);
  color: var(--on-band);
}
.seg-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.menu-wrap {
  position: relative;
}
.menu {
  position: absolute;
  right: 0;
  top: calc(100% + 6px);
  z-index: 30;
  min-width: 270px;
  padding: 6px;
  background: var(--sheet);
  border: 1px solid var(--rule-strong);
  border-radius: 8px;
  box-shadow: var(--shadow-pop);
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 10px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: var(--t-sm);
  text-align: left;
  cursor: pointer;
}
.menu-item:hover,
.menu-item:focus-visible {
  background: var(--sheet-2);
}
.menu-item:focus-visible {
  outline-offset: -2px;
}
.menu-item .icon {
  color: var(--ink-3);
}

.runbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: 10px var(--s-3);
  border-bottom: 1px solid var(--rule);
  background: var(--sheet);
}
.tempo {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: var(--t-xs);
  color: var(--ink-2);
}
.tempo label {
  font-weight: 650;
  color: var(--ink);
}
.tempo-out {
  min-width: 9ch;
  font-variant-numeric: tabular-nums;
}
.range {
  width: 108px;
  accent-color: var(--mode-band);
  height: 20px;
  margin: 0;
}

/* ---------------------------------------------------------------- editor */

.editor {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  flex: 1 1 auto;
  min-height: 0;
  background: var(--code-bg);
  font-family: var(--font-code);
  font-size: 14px;
  line-height: 24px;
  font-variant-ligatures: none;
}
.ed-gutter {
  overflow: hidden;
  min-width: 3.4em;
  background: var(--code-gutter);
  border-right: 1px solid var(--rule);
  color: var(--ink-3);
  text-align: right;
  user-select: none;
  font-variant-numeric: tabular-nums;
  font-size: 12.5px;
}
.ed-gutter-inner {
  padding: 12px 10px 12px 12px;
  will-change: transform;
}
.ed-gutter .ln {
  height: 24px;
}
.ed-gutter .ln.is-exec {
  color: var(--ink);
  font-weight: 700;
  background: var(--exec-bg);
  margin: 0 -10px 0 -12px;
  padding: 0 10px 0 12px;
}
.ed-gutter .ln.is-error {
  color: var(--error);
  font-weight: 800;
  background: var(--error-bg);
  margin: 0 -10px 0 -12px;
  padding: 0 10px 0 12px;
}
.ed-main {
  position: relative;
  overflow: hidden;
  min-width: 0;
}
.ed-main:focus-within {
  box-shadow: inset 0 0 0 2px var(--focus);
}
.ed-layer {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}
.ed-hl {
  padding: 12px 14px 48px;
  white-space: pre;
  tab-size: 2;
  color: var(--tok-name);
  width: max-content;
  min-width: 100%;
}
.ed-hl .ln {
  height: 24px;
  margin: 0 -14px;
  padding: 0 14px;
}
.ed-hl .ln.is-exec {
  background: var(--exec-bg);
  box-shadow: inset 0 1px var(--exec-rule), inset 0 -1px var(--exec-rule);
}
.ed-hl .ln.is-error {
  background: var(--error-bg);
}
.ed-probe {
  position: absolute;
  visibility: hidden;
}
.ed-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 12px 14px 48px;
  border: 0;
  outline: none;
  resize: none;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  font: inherit;
  line-height: 24px;
  white-space: pre;
  tab-size: 2;
  overflow: auto;
  font-variant-ligatures: none;
}
.ed-input::selection {
  background: var(--selection);
  color: transparent;
}
.t-cmd {
  color: var(--tok-cmd);
  font-weight: 650;
}
.t-ctl {
  color: var(--tok-ctl);
  font-weight: 750;
}
.t-ma {
  color: var(--tok-ctl);
}
.t-num {
  color: var(--tok-num);
}
.t-proc {
  color: var(--tok-proc);
  font-weight: 650;
}
.t-str {
  color: var(--tok-str);
  text-decoration: underline 3px var(--swatch, transparent);
  text-underline-offset: 5px;
}
.t-comment {
  color: var(--tok-comment);
  font-style: italic;
}
.t-bracket {
  color: var(--tok-bracket);
  font-weight: 800;
}
.t-paren,
.t-op {
  color: var(--tok-op);
}
.t-bad {
  color: var(--error);
}
.t-err {
  text-decoration: wavy underline var(--error) 1.5px;
  text-underline-offset: 4px;
  text-decoration-skip-ink: none;
}
.t-err-eol {
  display: inline-block;
  width: 1ch;
  border-bottom: 2px solid var(--error);
}
.ed-bubble {
  position: absolute;
  z-index: 2;
  max-width: min(46ch, 80%);
  padding: 6px 10px 7px;
  border-radius: 6px;
  background: var(--error-strong);
  color: var(--on-error);
  font-family: var(--font-ui);
  font-size: 13px;
  line-height: 1.35;
  white-space: normal;
  box-shadow: var(--shadow-pop);
}
.ed-bubble::before {
  content: '';
  position: absolute;
  left: 10px;
  top: -5px;
  border: 5px solid transparent;
  border-top: 0;
  border-bottom-color: var(--error-strong);
}

/* ---------------------------------------------------------------- status */

.status {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-height: 64px;
  padding: 11px 14px;
  border-top: 1px solid var(--rule-strong);
  background: var(--sheet);
}
.status > .icon {
  flex: none;
  margin-top: 1px;
}
.status-body {
  min-width: 0;
}
.status-main {
  margin: 0;
  font-weight: 650;
  font-size: var(--t-sm);
}
.status-sub {
  margin: 2px 0 0;
  color: var(--ink-2);
  font-size: var(--t-xs);
}
.status .btn {
  margin-left: auto;
  flex: none;
}
.status.is-error {
  background: var(--error-bg);
}
.status.is-error > .icon {
  color: var(--error);
}
.status.is-error .status-main strong {
  color: var(--error);
}
.status.is-done > .status-body .status-main {
  color: var(--mode);
}

/* ---------------------------------------------------------------- challenge panel */

.task {
  padding: 12px 14px 14px;
  border-bottom: 1px solid var(--rule);
  background: color-mix(in oklab, var(--fill-task) 9%, var(--sheet));
}
.task-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}
.task-title {
  margin: 0;
  font-size: 1.125rem;
  color: var(--ink-task);
}
.task-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: var(--t-xs);
  font-weight: 700;
  color: var(--ok);
}
.task-exit {
  margin-left: auto;
}
.task-text {
  margin: 8px 0 4px;
  max-width: 62ch;
}
.task-req {
  margin: 0 0 4px;
  font-size: var(--t-xs);
  color: var(--ink-2);
}
.task-hint summary {
  cursor: pointer;
  color: var(--ink-task);
  font-weight: 650;
  font-size: var(--t-sm);
  width: fit-content;
}
.task-hint p {
  margin: 4px 0 0;
  font-size: var(--t-sm);
  color: var(--ink-2);
}
.task-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 10px;
}
.check {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: var(--t-sm);
  cursor: pointer;
}
.check input {
  width: 17px;
  height: 17px;
  margin: 0;
  accent-color: var(--band-task);
}
.task-result:empty {
  display: none;
}
.task-result {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
  padding: 8px 10px;
  border-radius: var(--r-ctl);
  font-size: var(--t-sm);
}
.task-result .icon {
  flex: none;
  margin-top: 1px;
}
.task-result.is-pass {
  background: var(--ok-bg);
  color: var(--ink);
}
.task-result.is-pass .icon,
.task-result.is-pass strong {
  color: var(--ok);
}
.task-result.is-fail {
  background: var(--sheet);
  border: 1px solid var(--error-rule);
}
.task-result.is-fail .icon {
  color: var(--error);
}

/* ---------------------------------------------------------------- the chart */

.chart {
  display: grid;
  grid-template-rows: var(--band-h) minmax(0, 1fr) auto;
  min-width: 0;
  min-height: 0;
  background: var(--canvas);
}
.band {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  padding: 0 var(--s-3) 0 var(--s-5);
  background: var(--mode-band);
  color: var(--on-band);
  transition: background-color var(--t-med) var(--ease-out);
}
.band :focus-visible {
  outline-color: var(--on-band);
}
.band-head {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.band .band-title {
  margin: 0;
  font-size: var(--t-2xl);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.band-chip {
  flex: none;
  padding: 3px 7px 2px;
  border: 1.5px solid var(--on-band-2);
  border-radius: 3px;
  font-size: var(--t-xs);
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--on-band-2);
}
.band-tools {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: none;
}
.btn-band {
  color: var(--on-band);
  border-color: rgb(255 255 255 / 0.32);
}
.btn-band:hover {
  background: rgb(255 255 255 / 0.12);
}
.btn-band[aria-pressed='true'] {
  background: rgb(255 255 255 / 0.2);
  border-color: rgb(255 255 255 / 0.6);
}
.btn-band[hidden] {
  display: none;
}

.view-wrap {
  position: relative;
  min-height: 0;
  overflow: hidden;
  background: var(--canvas);
}
.view {
  position: absolute;
  inset: 0;
  touch-action: none;
  cursor: grab;
  outline: none;
}
.view.is-grabbing {
  cursor: grabbing;
}
.view:focus-visible {
  box-shadow: inset 0 0 0 3px var(--focus);
}
.view-canvas,
.view-overlay {
  position: absolute;
  inset: 0;
  display: block;
}
.view-overlay {
  pointer-events: none;
}
.view-notice {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  max-width: 62ch;
  margin: 0;
  padding: 10px 12px;
  background: var(--sheet);
  border: 1px solid var(--rule-strong);
  border-radius: var(--r-ctl);
  font-size: var(--t-sm);
  box-shadow: var(--shadow-pop);
}

.key {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 20px;
  min-height: var(--key-h);
  padding: 9px var(--s-5);
  border-top: 2px solid var(--ink);
  background: var(--sheet);
}
.key-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.key-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: var(--t-xs);
}
.key-n {
  display: inline-grid;
  place-items: center;
  width: 21px;
  height: 21px;
  border: 1.5px solid var(--ink);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.key-swatch {
  width: 22px;
  height: 10px;
  background: var(--swatch);
  border-radius: 2px;
}
.key-text code {
  font-size: 11.5px;
  color: var(--ink-2);
  margin-right: 2px;
}
.key-empty {
  font-size: var(--t-xs);
  color: var(--ink-3);
}
.readout {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: 0 0 0 auto;
  font-family: var(--font-code);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.ro {
  display: inline-flex;
  gap: 5px;
}
.ro-k {
  color: var(--ink-3);
}

/* ---------------------------------------------------------------- pages */

.page-band {
  padding: 32px clamp(16px, 4vw, 48px) 26px;
  background: var(--band-neutral);
  color: var(--on-band);
}
.page-band .band-title {
  margin: 0;
  font-size: var(--t-3xl);
}
.band-lead {
  max-width: 70ch;
  margin: 10px 0 0;
  color: var(--on-band-2);
  font-size: var(--t-md);
}
.band-task {
  background: var(--band-task);
}
.band-ref {
  background: var(--band-ref);
}
.page-body {
  max-width: 1320px;
  padding: 28px clamp(16px, 4vw, 48px) 72px;
}
.page-note {
  margin-top: 28px;
  color: var(--ink-3);
  font-size: var(--t-sm);
}

.cells-section + .cells-section {
  margin-top: 48px;
}
.section-title {
  margin: 0;
  padding-bottom: 8px;
  border-bottom: 2px solid currentColor;
  font-size: var(--t-xl);
  color: var(--ink-2d);
}
.cells-section[data-mode='3d'] .section-title {
  color: var(--ink-3d);
}
.section-lead {
  margin: 8px 0 18px;
  color: var(--ink-2);
}
.cells {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(232px, 1fr));
  gap: 16px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.cell {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--sheet);
  border: 1px solid var(--rule);
  border-radius: 4px;
  color: inherit;
  text-decoration: none;
  transition: border-color var(--t-fast) var(--ease-out), box-shadow var(--t-fast) var(--ease-out);
}
.cell:hover {
  border-color: var(--ink-3);
  box-shadow: 0 4px 14px -6px rgb(20 48 42 / 0.25);
}
.cell:hover .cell-title {
  text-decoration: underline;
  text-underline-offset: 0.2em;
}
.cell-figure {
  display: grid;
  place-items: center;
  aspect-ratio: 240 / 168;
  background: var(--canvas);
  border-bottom: 1px solid var(--rule);
  border-radius: 4px 4px 0 0;
  overflow: hidden;
}
.thumb {
  display: block;
  width: 100%;
  height: auto;
}
.cell-body {
  padding: 12px 14px 14px;
}
.cell-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: var(--t-md);
  font-weight: 720;
}
.cell-n {
  color: var(--ink-task);
  font-variant-numeric: tabular-nums;
}
.cell-text {
  margin: 4px 0 0;
  color: var(--ink-2);
  font-size: var(--t-sm);
}
.cell-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin: 10px 0 0;
  color: var(--ink-3);
  font-size: var(--t-xs);
}
.cell-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 650;
  color: var(--ink-2);
}
.cell-status.is-solved {
  color: var(--ok);
}
.cell-task.is-solved {
  border-color: color-mix(in oklab, var(--ok) 45%, var(--rule));
}
.tag {
  flex: none;
  padding: 2px 6px 1px;
  border-radius: 3px;
  color: var(--on-band);
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.4;
}
.tag-2d {
  background: var(--band-2d);
}
.tag-3d {
  background: var(--band-3d);
}

.tasks-summary {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 18px;
  margin-bottom: 22px;
}
.tasks-count {
  margin: 0;
}
.tasks-count strong {
  font-size: var(--t-lg);
  color: var(--ink-task);
}
.tasks-bar {
  display: flex;
  gap: 4px;
}
.tasks-tick {
  width: 24px;
  height: 8px;
  border-radius: 2px;
  background: var(--rule);
}
.tasks-tick.is-on {
  background: var(--fill-task);
}
.tasks-summary .btn-danger {
  margin-left: auto;
}

/* ---------------------------------------------------------------- reference */

.ref-layout {
  display: grid;
  grid-template-columns: 210px minmax(0, 76ch);
  gap: 48px;
}
.ref-toc {
  position: sticky;
  top: calc(var(--header-h) + 24px);
  align-self: start;
  font-size: var(--t-sm);
}
.ref-toc ol {
  margin: 0;
  padding: 0;
  list-style: none;
  border-left: 2px solid var(--rule);
}
.ref-toc a {
  display: block;
  padding: 5px 0 5px 14px;
  margin-left: -2px;
  border-left: 2px solid transparent;
  color: var(--ink-2);
  text-decoration: none;
}
.ref-toc a:hover {
  color: var(--ink);
  border-left-color: var(--ink-ref);
}
.ref-section + .ref-section {
  margin-top: 52px;
}
.ref-h2 {
  margin: 0 0 14px;
  padding-bottom: 8px;
  border-bottom: 2px solid currentColor;
  font-size: var(--t-xl);
  color: var(--ink-ref);
  scroll-margin-top: calc(var(--header-h) + 16px);
}
.ref-h2:focus {
  outline: none;
}
.ref-p {
  max-width: 70ch;
  margin: 0 0 12px;
}
.ref-p code,
.ref-table code,
.ref-text code {
  padding: 1px 5px;
  background: var(--sheet-2);
  border: 1px solid var(--rule);
  border-radius: 3px;
}
.ref-entry {
  padding: 18px 0 4px;
  border-top: 1px solid var(--rule);
}
.ref-entry:first-of-type {
  border-top: 0;
}
.ref-name {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  margin: 0 0 6px;
  font-weight: 400;
}
.ref-main {
  font-size: 1.0625rem;
  font-weight: 750;
  color: var(--tok-cmd);
}
.ref-alias {
  padding: 1px 6px;
  background: var(--sheet-2);
  border: 1px solid var(--rule);
  border-radius: 3px;
  color: var(--ink-2);
  font-size: 0.8125rem;
}
.ref-arg {
  margin: 0 0 4px;
  font-size: var(--t-sm);
  color: var(--ink-2);
}
.ref-arg-k {
  font-weight: 650;
  color: var(--ink);
}
.ref-text {
  max-width: 70ch;
  margin: 0;
}
.ref-ex {
  margin-top: 16px;
}
.ref-example {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  margin: 12px 0 8px;
  background: var(--code-bg);
  border: 1px solid var(--rule-strong);
  border-radius: 4px;
  overflow: hidden;
}
.ref-code {
  margin: 0;
  padding: 12px 14px;
  overflow-x: auto;
  font-size: 13.5px;
  line-height: 1.65;
}
.ref-fig {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 6px 8px 8px;
  border-left: 1px solid var(--rule);
  background: var(--canvas);
}
.ref-fig .thumb {
  width: 132px;
}
.ref-fig-empty {
  margin: 0;
  max-width: 18ch;
  font-size: var(--t-xs);
  color: var(--ink-3);
}
.table-wrap {
  overflow-x: auto;
  margin: 6px 0 14px;
}
.ref-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--t-sm);
}
.ref-table th,
.ref-table td {
  padding: 8px 10px;
  border-bottom: 1px solid var(--rule);
  text-align: left;
  vertical-align: top;
}
.ref-table thead th {
  border-bottom: 2px solid var(--ink);
  font-weight: 750;
}
.ref-table tbody th {
  font-weight: 600;
}
kbd {
  display: inline-block;
  padding: 1px 6px;
  border: 1px solid var(--rule-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--sheet);
  color: var(--ink);
  font-size: 0.8125rem;
  line-height: 1.5;
  white-space: nowrap;
}

/* ---------------------------------------------------------------- popover & toasts */

.popover {
  position: fixed;
  inset: auto;
  top: calc(var(--header-h) + 8px);
  right: 12px;
  margin: 0;
  width: min(380px, calc(100vw - 24px));
  padding: 16px 18px;
  background: var(--sheet);
  color: var(--ink);
  border: 1px solid var(--rule-strong);
  border-radius: 8px;
  box-shadow: var(--shadow-pop);
}
.popover-title {
  margin: 0;
  font-size: var(--t-md);
  font-weight: 750;
}
.keys-list {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 9px 14px;
  margin: 12px 0 14px;
  font-size: var(--t-sm);
}
.keys-list dd {
  margin: 0;
  color: var(--ink-2);
}
.popover-link {
  font-size: var(--t-sm);
  font-weight: 650;
  color: var(--ink-ref);
}

.toasts {
  position: fixed;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(580px, calc(100vw - 24px));
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 7px 7px 14px;
  background: var(--header);
  color: var(--on-header);
  border-radius: 7px;
  box-shadow: var(--shadow-pop);
  font-size: var(--t-sm);
  pointer-events: auto;
  animation: toast-in var(--t-med) var(--ease-out);
}
.toast.is-leaving {
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 160ms ease-in, transform 160ms ease-in;
}
.toast-msg {
  flex: 1;
  min-width: 0;
}
.toast > .icon {
  flex: none;
  color: #4cc59c;
}
.toast-error > .icon {
  color: #ff8a6e;
}
.toast .btn-quiet {
  background: transparent;
  color: var(--on-header);
  border-color: rgb(255 255 255 / 0.35);
}
.toast .btn-quiet:hover {
  background: rgb(255 255 255 / 0.1);
  border-color: rgb(255 255 255 / 0.6);
}
.toast-close {
  color: var(--on-header-2);
}
.toast-close:hover {
  color: var(--on-header);
  background: rgb(255 255 255 / 0.1);
}
.toast :focus-visible {
  outline-color: var(--on-header);
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

.noscript {
  padding: 24px;
}

/* ---------------------------------------------------------------- responsive */

@media (max-width: 1100px) {
  .studio {
    grid-template-columns: minmax(360px, 42%) minmax(0, 1fr);
  }
  .tempo {
    margin-left: 0;
    flex-basis: 100%;
  }
}

@media (max-width: 860px) {
  .app-header {
    position: static;
    flex-wrap: wrap;
    height: auto;
    padding: 0 var(--s-2) 0 var(--s-3);
    gap: 0;
  }
  .brand {
    height: 48px;
  }
  .nav {
    order: 3;
    flex-basis: 100%;
    margin: 0 calc(-1 * var(--s-2)) 0 calc(-1 * var(--s-3));
    border-top: 1px solid rgb(255 255 255 / 0.1);
  }
  .nav-link {
    flex: 1;
    justify-content: center;
    height: 44px;
    padding: 3px 4px 0;
  }
  .studio {
    display: flex;
    flex-direction: column;
    height: auto;
    min-height: 0;
  }
  .chart {
    order: -1;
    grid-template-rows: auto minmax(300px, 50vh) auto;
  }
  .band {
    min-height: 52px;
    padding: 6px 6px 6px 14px;
  }
  .band .band-title {
    font-size: var(--t-xl);
  }
  .band .btn-label {
    display: none;
  }
  .btn-band {
    width: 36px;
    padding: 0;
  }
  .key {
    padding: 8px 14px;
  }
  .readout {
    margin-left: 0;
  }
  .studio-code {
    border-right: 0;
    border-top: 1px solid var(--rule-strong);
  }
  .runbar {
    position: sticky;
    top: 0;
    z-index: 10;
    box-shadow: 0 1px 0 var(--rule);
  }
  .editor {
    flex: none;
    height: max(300px, 52vh);
  }
  .ref-layout {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
  .ref-toc {
    position: static;
  }
  .ref-toc ol {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    border: 0;
  }
  .ref-toc a {
    margin: 0;
    padding: 4px 10px;
    border: 1px solid var(--rule-strong);
    border-radius: 999px;
    background: var(--sheet);
  }
  .ref-toc a:hover {
    border-color: var(--ink-ref);
  }
}

@media (max-width: 480px) {
  .brand-name {
    font-size: 1.25rem;
  }
  .runbar .btn {
    padding: 0 10px;
  }
  .runbar .btn-primary {
    padding: 0 14px;
  }
  .ref-example {
    grid-template-columns: minmax(0, 1fr);
  }
  .ref-fig {
    flex-direction: row;
    border-left: 0;
    border-top: 1px solid var(--rule);
  }
  .page-band .band-title {
    font-size: var(--t-2xl);
  }
  .cells {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

@media (forced-colors: active) {
  .btn,
  .seg-btn {
    border: 1px solid ButtonText;
  }
  .ed-input {
    color: CanvasText;
  }
  .ed-layer {
    display: none;
  }
}

toolu_01AzFVFbakTdRRrTBDrQUYDD.content:
/* ------------------------------------------------------------------ base */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  scrollbar-color: var(--rule-strong) transparent;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: var(--t-md);
  line-height: 1.45;
  font-variant-numeric: lining-nums;
  min-height: 100dvh;
}

::selection {
  background: var(--selection);
}

a {
  color: inherit;
  text-underline-offset: 0.2em;
  text-decoration-thickness: 1px;
}

code,
kbd,
pre {
  font-family: var(--font-code);
  font-size: 0.92em;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  background: var(--sheet);
  color: var(--ink);
  padding: 8px 14px;
  border-radius: var(--r-ctl);
  box-shadow: var(--shadow-pop);
  font-weight: 600;
}
.skip-link:focus {
  top: 8px;
}

main:focus {
  outline: none;
}

/* chart lettering: condensed grotesque caps, as on a printed wall chart */
.band-title,
.section-title,
.ref-h2,
.task-title,
.brand-name {
  font-stretch: 68%;
  font-weight: 780;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1;
  text-wrap: balance;
}

/* ------------------------------------------------------------------ buttons */

.btn {
  --btn-h: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: var(--btn-h);
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: var(--r-ctl);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: var(--t-sm);
  font-weight: 650;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition:
    background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out),
    color var(--t-fast) var(--ease-out);
}
.btn .icon {
  flex: none;
}
.btn:disabled,
.btn[aria-disabled='true'] {
  opacity: 0.42;
  cursor: not-allowed;
}
.btn-sm {
  --btn-h: 30px;
  padding: 0 10px;
  font-size: var(--t-xs);
}
.btn-icon {
  width: var(--btn-h);
  padding: 0;
}
.btn-quiet {
  background: var(--sheet);
  border-color: var(--rule-strong);
}
.btn-quiet:hover:not(:disabled) {
  background: var(--sheet-2);
  border-color: var(--ink-3);
}
.btn-quiet:active:not(:disabled) {
  background: var(--rule);
}
.btn-primary {
  background: var(--mode-band);
  color: var(--on-band);
  padding: 0 16px;
}
.btn-primary:hover:not(:disabled) {
  background: color-mix(in oklab, var(--mode-band) 84%, #000);
}
.btn-primary:active:not(:disabled) {
  background: color-mix(in oklab, var(--mode-band) 72%, #000);
}
.btn-task {
  background: var(--band-task);
  color: var(--on-band);
  padding: 0 16px;
}
.btn-task:hover {
  background: color-mix(in oklab, var(--band-task) 84%, #000);
}
.btn-danger {
  color: var(--error);
  border-color: var(--error-rule);
}
.btn-danger:hover:not(:disabled) {
  background: var(--error-bg);
  border-color: var(--error);
}

/* ------------------------------------------------------------------ header */

.app-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: stretch;
  gap: var(--s-4);
  height: var(--header-h);
  padding: 0 var(--s-3) 0 var(--s-4);
  background: var(--header);
  color: var(--on-header);
  --brand-turtle: #4cc59c;
}
.app-header :focus-visible {
  outline-color: var(--on-header);
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--on-header);
  text-decoration: none;
  padding-right: var(--s-2);
}
.brand-mark {
  color: var(--on-header);
}
.brand-name {
  font-size: 1.375rem;
  letter-spacing: 0.04em;
}
.nav {
  display: flex;
  align-items: stretch;
}
.nav-link {
  display: flex;
  align-items: center;
  padding: 0 14px;
  color: var(--on-header-2);
  text-decoration: none;
  font-weight: 600;
  font-size: var(--t-sm);
  border-bottom: 3px solid transparent;
  padding-top: 3px;
  transition: color var(--t-fast) var(--ease-out);
}
.nav-link:hover {
  color: var(--on-header);
}
.nav-link[aria-current='page'] {
  color: var(--on-header);
}
.nav-link:nth-child(1)[aria-current='page'] {
  border-bottom-color: #4cc59c;
}
.nav-link:nth-child(2)[aria-current='page'] {
  border-bottom-color: #86b6ec;
}
.nav-link:nth-child(3)[aria-current='page'] {
  border-bottom-color: #e6a669;
}
.nav-link:nth-child(4)[aria-current='page'] {
  border-bottom-color: #cba8e6;
}
.nav-link:focus-visible {
  outline-offset: -4px;
}
.header-tools {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
}
.btn-header {
  color: var(--on-header-2);
}
.btn-header:hover {
  color: var(--on-header);
  background: rgb(255 255 255 / 0.08);
}

/* ------------------------------------------------------------------ studio */

.studio {
  --mode: var(--ink-2d);
  --mode-fill: var(--fill-2d);
  --mode-band: var(--band-2d);
  display: grid;
  grid-template-columns: minmax(400px, 36%) minmax(0, 1fr);
  height: calc(100dvh - var(--header-h));
  min-height: 560px;
}
.studio[data-mode='3d'] {
  --mode: var(--ink-3d);
  --mode-fill: var(--fill-3d);
  --mode-band: var(--band-3d);
}

.studio-code {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  background: var(--sheet);
  border-right: 1px solid var(--rule-strong);
}

.code-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  padding: 10px var(--s-3);
  border-bottom: 1px solid var(--rule);
}

.seg {
  display: inline-flex;
  padding: 2px;
  border: 1px solid var(--rule-strong);
  border-radius: 7px;
  background: var(--sheet-2);
}
.seg-btn {
  min-width: 56px;
  height: 30px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--ink-2);
  font: inherit;
  font-weight: 750;
  font-size: var(--t-sm);
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: background-color var(--t-fast) var(--ease-out), color var(--t-fast) var(--ease-out);
}
.seg-btn:hover:not(:disabled):not([aria-pressed='true']) {
  color: var(--ink);
  background: var(--rule);
}
.seg-btn[aria-pressed='true']:nth-child(1) {
  background: var(--band-2d);
  color: var(--on-band);
}
.seg-btn[aria-pressed='true']:nth-child(2) {
  background: var(--band-3d);
  color: var(--on-band);
}
.seg-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.menu-wrap {
  position: relative;
}
.menu {
  position: absolute;
  right: 0;
  top: calc(100% + 6px);
  z-index: 30;
  min-width: 270px;
  padding: 6px;
  background: var(--sheet);
  border: 1px solid var(--rule-strong);
  border-radius: 8px;
  box-shadow: var(--shadow-pop);
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 10px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: var(--t-sm);
  text-align: left;
  cursor: pointer;
}
.menu-item:hover,
.menu-item:focus-visible {
  background: var(--sheet-2);
}
.menu-item:focus-visible {
  outline-offset: -2px;
}
.menu-item .icon {
  color: var(--ink-3);
}

.runbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: 10px var(--s-3);
  border-bottom: 1px solid var(--rule);
  background: var(--sheet);
}
.tempo {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: var(--t-xs);
  color: var(--ink-2);
}
.tempo label {
  font-weight: 650;
  color: var(--ink);
}
.tempo-out {
  min-width: 9ch;
  font-variant-numeric: tabular-nums;
}
.range {
  width: 108px;
  accent-color: var(--mode-band);
  height: 20px;
  margin: 0;
}

/* ---------------------------------------------------------------- editor */

.editor {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  flex: 1 1 auto;
  min-height: 0;
  background: var(--code-bg);
  font-family: var(--font-code);
  font-size: 14px;
  line-height: 24px;
  font-variant-ligatures: none;
}
.ed-gutter {
  overflow: hidden;
  min-width: 3.4em;
  background: var(--code-gutter);
  border-right: 1px solid var(--rule);
  color: var(--ink-3);
  text-align: right;
  user-select: none;
  font-variant-numeric: tabular-nums;
  font-size: 12.5px;
}
.ed-gutter-inner {
  padding: 12px 10px 12px 12px;
  will-change: transform;
}
.ed-gutter .ln {
  height: 24px;
}
.ed-gutter .ln.is-exec {
  color: var(--ink);
  font-weight: 700;
  background: var(--exec-bg);
  margin: 0 -10px 0 -12px;
  padding: 0 10px 0 12px;
}
.ed-gutter .ln.is-error {
  color: var(--error);
  font-weight: 800;
  background: var(--error-bg);
  margin: 0 -10px 0 -12px;
  padding: 0 10px 0 12px;
}
.ed-main {
  position: relative;
  overflow: hidden;
  min-width: 0;
}
.ed-main:focus-within {
  box-shadow: inset 0 0 0 2px var(--focus);
}
.ed-layer {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}
.ed-hl {
  padding: 12px 14px 48px;
  white-space: pre;
  tab-size: 2;
  color: var(--tok-name);
  width: max-content;
  min-width: 100%;
}
.ed-hl .ln {
  height: 24px;
  margin: 0 -14px;
  padding: 0 14px;
}
.ed-hl .ln.is-exec {
  background: var(--exec-bg);
  box-shadow: inset 0 1px var(--exec-rule), inset 0 -1px var(--exec-rule);
}
.ed-hl .ln.is-error {
  background: var(--error-bg);
}
.ed-probe {
  position: absolute;
  visibility: hidden;
}
.ed-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 12px 14px 48px;
  border: 0;
  outline: none;
  resize: none;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  font: inherit;
  line-height: 24px;
  white-space: pre;
  tab-size: 2;
  overflow: auto;
  font-variant-ligatures: none;
}
.ed-input::selection {
  background: var(--selection);
  color: transparent;
}
.t-cmd {
  color: var(--tok-cmd);
  font-weight: 650;
}
.t-ctl {
  color: var(--tok-ctl);
  font-weight: 750;
}
.t-ma {
  color: var(--tok-ctl);
}
.t-num {
  color: var(--tok-num);
}
.t-proc {
  color: var(--tok-proc);
  font-weight: 650;
}
.t-str {
  color: var(--tok-str);
  text-decoration: underline 3px var(--swatch, transparent);
  text-underline-offset: 5px;
}
.t-comment {
  color: var(--tok-comment);
  font-style: italic;
}
.t-bracket {
  color: var(--tok-bracket);
  font-weight: 800;
}
.t-paren,
.t-op {
  color: var(--tok-op);
}
.t-bad {
  color: var(--error);
}
.t-err {
  text-decoration: wavy underline var(--error) 1.5px;
  text-underline-offset: 4px;
  text-decoration-skip-ink: none;
}
.t-err-eol {
  display: inline-block;
  width: 1ch;
  border-bottom: 2px solid var(--error);
}
.ed-bubble {
  position: absolute;
  z-index: 2;
  max-width: min(46ch, 80%);
  padding: 6px 10px 7px;
  border-radius: 6px;
  background: var(--error-strong);
  color: var(--on-error);
  font-family: var(--font-ui);
  font-size: 13px;
  line-height: 1.35;
  white-space: normal;
  box-shadow: var(--shadow-pop);
}
.ed-bubble::before {
  content: '';
  position: absolute;
  left: 10px;
  top: -5px;
  border: 5px solid transparent;
  border-top: 0;
  border-bottom-color: var(--error-strong);
}

/* ---------------------------------------------------------------- status */

.status {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-height: 64px;
  padding: 11px 14px;
  border-top: 1px solid var(--rule-strong);
  background: var(--sheet);
}
.status > .icon {
  flex: none;
  margin-top: 1px;
}
.status-body {
  min-width: 0;
}
.status-main {
  margin: 0;
  font-weight: 650;
  font-size: var(--t-sm);
}
.status-sub {
  margin: 2px 0 0;
  color: var(--ink-2);
  font-size: var(--t-xs);
}
.status .btn {
  margin-left: auto;
  flex: none;
}
.status.is-error {
  background: var(--error-bg);
}
.status.is-error > .icon {
  color: var(--error);
}
.status.is-error .status-main strong {
  color: var(--error);
}
.status.is-done > .status-body .status-main {
  color: var(--mode);
}

/* ---------------------------------------------------------------- challenge panel */

.task {
  padding: 12px 14px 14px;
  border-bottom: 1px solid var(--rule);
  background: color-mix(in oklab, var(--fill-task) 9%, var(--sheet));
}
.task-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}
.task-title {
  margin: 0;
  font-size: 1.125rem;
  color: var(--ink-task);
}
.task-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: var(--t-xs);
  font-weight: 700;
  color: var(--ok);
}
.task-exit {
  margin-left: auto;
}
.task-text {
  margin: 8px 0 4px;
  max-width: 62ch;
}
.task-req {
  margin: 0 0 4px;
  font-size: var(--t-xs);
  color: var(--ink-2);
}
.task-hint summary {
  cursor: pointer;
  color: var(--ink-task);
  font-weight: 650;
  font-size: var(--t-sm);
  width: fit-content;
}
.task-hint p {
  margin: 4px 0 0;
  font-size: var(--t-sm);
  color: var(--ink-2);
}
.task-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 10px;
}
.check {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: var(--t-sm);
  cursor: pointer;
}
.check input {
  width: 17px;
  height: 17px;
  margin: 0;
  accent-color: var(--band-task);
}
.task-result:empty {
  display: none;
}
.task-result {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
  padding: 8px 10px;
  border-radius: var(--r-ctl);
  font-size: var(--t-sm);
}
.task-result .icon {
  flex: none;
  margin-top: 1px;
}
.task-result.is-pass {
  background: var(--ok-bg);
  color: var(--ink);
}
.task-result.is-pass .icon,
.task-result.is-pass strong {
  color: var(--ok);
}
.task-result.is-fail {
  background: var(--sheet);
  border: 1px solid var(--error-rule);
}
.task-result.is-fail .icon {
  color: var(--error);
}

/* ---------------------------------------------------------------- the chart */

.chart {
  display: grid;
  grid-template-rows: var(--band-h) minmax(0, 1fr) auto;
  min-width: 0;
  min-height: 0;
  background: var(--canvas);
}
.band {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  padding: 0 var(--s-3) 0 var(--s-5);
  background: var(--mode-band);
  color: var(--on-band);
  transition: background-color var(--t-med) var(--ease-out);
}
.band :focus-visible {
  outline-color: var(--on-band);
}
.band-head {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.band .band-title {
  margin: 0;
  font-size: var(--t-2xl);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.band-chip {
  flex: none;
  padding: 3px 7px 2px;
  border: 1.5px solid var(--on-band-2);
  border-radius: 3px;
  font-size: var(--t-xs);
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--on-band-2);
}
.band-tools {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: none;
}
.btn-band {
  color: var(--on-band);
  border-color: rgb(255 255 255 / 0.32);
}
.btn-band:hover {
  background: rgb(255 255 255 / 0.12);
}
.btn-band[aria-pressed='true'] {
  background: rgb(255 255 255 / 0.2);
  border-color: rgb(255 255 255 / 0.6);
}
.btn-band[hidden] {
  display: none;
}

.view-wrap {
  position: relative;
  min-height: 0;
  overflow: hidden;
  background: var(--canvas);
}
.view {
  position: absolute;
  inset: 0;
  touch-action: none;
  cursor: grab;
  outline: none;
}
.view.is-grabbing {
  cursor: grabbing;
}
.view:focus-visible {
  box-shadow: inset 0 0 0 3px var(--focus);
}
.view-canvas,
.view-overlay {
  position: absolute;
  inset: 0;
  display: block;
}
.view-overlay {
  pointer-events: none;
}
.view-notice {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  max-width: 62ch;
  margin: 0;
  padding: 10px 12px;
  background: var(--sheet);
  border: 1px solid var(--rule-strong);
  border-radius: var(--r-ctl);
  font-size: var(--t-sm);
  box-shadow: var(--shadow-pop);
}

.key {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 20px;
  min-height: var(--key-h);
  padding: 9px var(--s-5);
  border-top: 2px solid var(--ink);
  background: var(--sheet);
}
.key-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.key-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: var(--t-xs);
}
.key-n {
  display: inline-grid;
  place-items: center;
  width: 21px;
  height: 21px;
  border: 1.5px solid var(--ink);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.key-swatch {
  width: 22px;
  height: 10px;
  background: var(--swatch);
  border-radius: 2px;
}
.key-text code {
  font-size: 11.5px;
  color: var(--ink-2);
  margin-right: 2px;
}
.key-empty {
  font-size: var(--t-xs);
  color: var(--ink-3);
}
.readout {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: 0 0 0 auto;
  font-family: var(--font-code);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.ro {
  display: inline-flex;
  gap: 5px;
}
.ro-k {
  color: var(--ink-3);
}

/* ---------------------------------------------------------------- pages */

.page-band {
  padding: 32px clamp(16px, 4vw, 48px) 26px;
  background: var(--band-neutral);
  color: var(--on-band);
}
.page-band .band-title {
  margin: 0;
  font-size: var(--t-3xl);
}
.band-lead {
  max-width: 70ch;
  margin: 10px 0 0;
  color: var(--on-band-2);
  font-size: var(--t-md);
}
.band-task {
  background: var(--band-task);
}
.band-ref {
  background: var(--band-ref);
}
.page-body {
  max-width: 1320px;
  padding: 28px clamp(16px, 4vw, 48px) 72px;
}
.page-note {
  margin-top: 28px;
  color: var(--ink-3);
  font-size: var(--t-sm);
}

.cells-section + .cells-section {
  margin-top: 48px;
}
.section-title {
  margin: 0;
  padding-bottom: 8px;
  border-bottom: 2px solid currentColor;
  font-size: var(--t-xl);
  color: var(--ink-2d);
}
.cells-section[data-mode='3d'] .section-title {
  color: var(--ink-3d);
}
.section-lead {
  margin: 8px 0 18px;
  color: var(--ink-2);
}
.cells {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(232px, 1fr));
  gap: 16px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.cell {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--sheet);
  border: 1px solid var(--rule);
  border-radius: 4px;
  color: inherit;
  text-decoration: none;
  transition: border-color var(--t-fast) var(--ease-out), box-shadow var(--t-fast) var(--ease-out);
}
.cell:hover {
  border-color: var(--ink-3);
  box-shadow: 0 4px 14px -6px rgb(20 48 42 / 0.25);
}
.cell:hover .cell-title {
  text-decoration: underline;
  text-underline-offset: 0.2em;
}
.cell-figure {
  display: grid;
  place-items: center;
  aspect-ratio: 240 / 168;
  background: var(--canvas);
  border-bottom: 1px solid var(--rule);
  border-radius: 4px 4px 0 0;
  overflow: hidden;
}
.thumb {
  display: block;
  width: 100%;
  height: auto;
}
.cell-body {
  padding: 12px 14px 14px;
}
.cell-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: var(--t-md);
  font-weight: 720;
}
.cell-n {
  color: var(--ink-task);
  font-variant-numeric: tabular-nums;
}
.cell-text {
  margin: 4px 0 0;
  color: var(--ink-2);
  font-size: var(--t-sm);
}
.cell-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin: 10px 0 0;
  color: var(--ink-3);
  font-size: var(--t-xs);
}
.cell-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 650;
  color: var(--ink-2);
}
.cell-status.is-solved {
  color: var(--ok);
}
.cell-task.is-solved {
  border-color: color-mix(in oklab, var(--ok) 45%, var(--rule));
}
.tag {
  flex: none;
  padding: 2px 6px 1px;
  border-radius: 3px;
  color: var(--on-band);
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.4;
}
.tag-2d {
  background: var(--band-2d);
}
.tag-3d {
  background: var(--band-3d);
}

.tasks-summary {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 18px;
  margin-bottom: 22px;
}
.tasks-count {
  margin: 0;
}
.tasks-count strong {
  font-size: var(--t-lg);
  color: var(--ink-task);
}
.tasks-bar {
  display: flex;
  gap: 4px;
}
.tasks-tick {
  width: 24px;
  height: 8px;
  border-radius: 2px;
  background: var(--rule);
}
.tasks-tick.is-on {
  background: var(--fill-task);
}
.tasks-summary .btn-danger {
  margin-left: auto;
}

/* ---------------------------------------------------------------- reference */

.ref-layout {
  display: grid;
  grid-template-columns: 210px minmax(0, 76ch);
  gap: 48px;
}
.ref-toc {
  position: sticky;
  top: calc(var(--header-h) + 24px);
  align-self: start;
  font-size: var(--t-sm);
}
.ref-toc ol {
  margin: 0;
  padding: 0;
  list-style: none;
  border-left: 2px solid var(--rule);
}
.ref-toc a {
  display: block;
  padding: 5px 0 5px 14px;
  margin-left: -2px;
  border-left: 2px solid transparent;
  color: var(--ink-2);
  text-decoration: none;
}
.ref-toc a:hover {
  color: var(--ink);
  border-left-color: var(--ink-ref);
}
.ref-section + .ref-section {
  margin-top: 52px;
}
.ref-h2 {
  margin: 0 0 14px;
  padding-bottom: 8px;
  border-bottom: 2px solid currentColor;
  font-size: var(--t-xl);
  color: var(--ink-ref);
  scroll-margin-top: calc(var(--header-h) + 16px);
}
.ref-h2:focus {
  outline: none;
}
.ref-p {
  max-width: 70ch;
  margin: 0 0 12px;
}
.ref-p code,
.ref-table code,
.ref-text code {
  padding: 1px 5px;
  background: var(--sheet-2);
  border: 1px solid var(--rule);
  border-radius: 3px;
}
.ref-entry {
  padding: 18px 0 4px;
  border-top: 1px solid var(--rule);
}
.ref-entry:first-of-type {
  border-top: 0;
}
.ref-name {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  margin: 0 0 6px;
  font-weight: 400;
}
.ref-main {
  font-size: 1.0625rem;
  font-weight: 750;
  color: var(--tok-cmd);
}
.ref-alias {
  padding: 1px 6px;
  background: var(--sheet-2);
  border: 1px solid var(--rule);
  border-radius: 3px;
  color: var(--ink-2);
  font-size: 0.8125rem;
}
.ref-arg {
  margin: 0 0 4px;
  font-size: var(--t-sm);
  color: var(--ink-2);
}
.ref-arg-k {
  font-weight: 650;
  color: var(--ink);
}
.ref-text {
  max-width: 70ch;
  margin: 0;
}
.ref-ex {
  margin-top: 16px;
}
.ref-example {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  margin: 12px 0 8px;
  background: var(--code-bg);
  border: 1px solid var(--rule-strong);
  border-radius: 4px;
  overflow: hidden;
}
.ref-code {
  margin: 0;
  padding: 12px 14px;
  overflow-x: auto;
  font-size: 13.5px;
  line-height: 1.65;
}
.ref-fig {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 6px 8px 8px;
  border-left: 1px solid var(--rule);
  background: var(--canvas);
}
.ref-fig .thumb {
  width: 132px;
}
.ref-fig-empty {
  margin: 0;
  max-width: 18ch;
  font-size: var(--t-xs);
  color: var(--ink-3);
}
.table-wrap {
  overflow-x: auto;
  margin: 6px 0 14px;
}
.ref-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--t-sm);
}
.ref-table th,
.ref-table td {
  padding: 8px 10px;
  border-bottom: 1px solid var(--rule);
  text-align: left;
  vertical-align: top;
}
.ref-table thead th {
  border-bottom: 2px solid var(--ink);
  font-weight: 750;
}
.ref-table tbody th {
  font-weight: 600;
}
kbd {
  display: inline-block;
  padding: 1px 6px;
  border: 1px solid var(--rule-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--sheet);
  color: var(--ink);
  font-size: 0.8125rem;
  line-height: 1.5;
  white-space: nowrap;
}

/* ---------------------------------------------------------------- popover & toasts */

.popover {
  position: fixed;
  inset: auto;
  top: calc(var(--header-h) + 8px);
  right: 12px;
  margin: 0;
  width: min(380px, calc(100vw - 24px));
  padding: 16px 18px;
  background: var(--sheet);
  color: var(--ink);
  border: 1px solid var(--rule-strong);
  border-radius: 8px;
  box-shadow: var(--shadow-pop);
}
.popover-title {
  margin: 0;
  font-size: var(--t-md);
  font-weight: 750;
}
.keys-list {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 9px 14px;
  margin: 12px 0 14px;
  font-size: var(--t-sm);
}
.keys-list dd {
  margin: 0;
  color: var(--ink-2);
}
.popover-link {
  font-size: var(--t-sm);
  font-weight: 650;
  color: var(--ink-ref);
}

.toasts {
  position: fixed;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(580px, calc(100vw - 24px));
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 7px 7px 14px;
  background: var(--header);
  color: var(--on-header);
  border-radius: 7px;
  box-shadow: var(--shadow-pop);
  font-size: var(--t-sm);
  pointer-events: auto;
  animation: toast-in var(--t-med) var(--ease-out);
}
.toast.is-leaving {
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 160ms ease-in, transform 160ms ease-in;
}
.toast-msg {
  flex: 1;
  min-width: 0;
}
.toast > .icon {
  flex: none;
  color: #4cc59c;
}
.toast-error > .icon {
  color: #ff8a6e;
}
.toast .btn-quiet {
  background: transparent;
  color: var(--on-header);
  border-color: rgb(255 255 255 / 0.35);
}
.toast .btn-quiet:hover {
  background: rgb(255 255 255 / 0.1);
  border-color: rgb(255 255 255 / 0.6);
}
.toast-close {
  color: var(--on-header-2);
}
.toast-close:hover {
  color: var(--on-header);
  background: rgb(255 255 255 / 0.1);
}
.toast :focus-visible {
  outline-color: var(--on-header);
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

.noscript {
  padding: 24px;
}

/* ---------------------------------------------------------------- responsive */

@media (max-width: 1100px) {
  .studio {
    grid-template-columns: minmax(360px, 42%) minmax(0, 1fr);
  }
  .tempo {
    margin-left: 0;
    flex-basis: 100%;
  }
}

@media (max-width: 860px) {
  .app-header {
    position: static;
    flex-wrap: wrap;
    height: auto;
    padding: 0 var(--s-2) 0 var(--s-3);
    gap: 0;
  }
  .brand {
    height: 48px;
  }
  .nav {
    order: 3;
    flex-basis: 100%;
    margin: 0 calc(-1 * var(--s-2)) 0 calc(-1 * var(--s-3));
    border-top: 1px solid rgb(255 255 255 / 0.1);
  }
  .nav-link {
    flex: 1;
    justify-content: center;
    height: 44px;
    padding: 3px 4px 0;
  }
  .studio {
    display: flex;
    flex-direction: column;
    height: auto;
    min-height: 0;
  }
  .chart {
    order: -1;
    grid-template-rows: auto minmax(300px, 50vh) auto;
  }
  .band {
    min-height: 52px;
    padding: 6px 6px 6px 14px;
  }
  .band .band-title {
    font-size: var(--t-xl);
  }
  .band .btn-label {
    display: none;
  }
  .btn-band {
    width: 36px;
    padding: 0;
  }
  .key {
    padding: 8px 14px;
  }
  .readout {
    margin-left: 0;
  }
  .studio-code {
    border-right: 0;
    border-top: 1px solid var(--rule-strong);
  }
  .runbar {
    position: sticky;
    top: 0;
    z-index: 10;
    box-shadow: 0 1px 0 var(--rule);
  }
  .editor {
    flex: none;
    height: max(300px, 52vh);
  }
  .ref-layout {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
  .ref-toc {
    position: static;
  }
  .ref-toc ol {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    border: 0;
  }
  .ref-toc a {
    margin: 0;
    padding: 4px 10px;
    border: 1px solid var(--rule-strong);
    border-radius: 999px;
    background: var(--sheet);
  }
  .ref-toc a:hover {
    border-color: var(--ink-ref);
  }
}

@media (max-width: 480px) {
  .brand-name {
    font-size: 1.25rem;
  }
  .runbar .btn {
    padding: 0 10px;
  }
  .runbar .btn-primary {
    padding: 0 14px;
  }
  .ref-example {
    grid-template-columns: minmax(0, 1fr);
  }
  .ref-fig {
    flex-direction: row;
    border-left: 0;
    border-top: 1px solid var(--rule);
  }
  .page-band .band-title {
    font-size: var(--t-2xl);
  }
  .cells {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

@media (forced-colors: active) {
  .btn,
  .seg-btn {
    border: 1px solid ButtonText;
  }
  .ed-input {
    color: CanvasText;
  }
  .ed-layer {
    display: none;
  }
}

tool_use_result.content:
/* ------------------------------------------------------------------ base */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  scrollbar-color: var(--rule-strong) transparent;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: var(--t-md);
  line-height: 1.45;
  font-variant-numeric: lining-nums;
  min-height: 100dvh;
}

::selection {
  background: var(--selection);
}

a {
  color: inherit;
  text-underline-offset: 0.2em;
  text-decoration-thickness: 1px;
}

code,
kbd,
pre {
  font-family: var(--font-code);
  font-size: 0.92em;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  background: var(--sheet);
  color: var(--ink);
  padding: 8px 14px;
  border-radius: var(--r-ctl);
  box-shadow: var(--shadow-pop);
  font-weight: 600;
}
.skip-link:focus {
  top: 8px;
}

main:focus {
  outline: none;
}

/* chart lettering: condensed grotesque caps, as on a printed wall chart */
.band-title,
.section-title,
.ref-h2,
.task-title,
.brand-name {
  font-stretch: 68%;
  font-weight: 780;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1;
  text-wrap: balance;
}

/* ------------------------------------------------------------------ buttons */

.btn {
  --btn-h: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: var(--btn-h);
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: var(--r-ctl);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: var(--t-sm);
  font-weight: 650;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition:
    background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out),
    color var(--t-fast) var(--ease-out);
}
.btn .icon {
  flex: none;
}
.btn:disabled,
.btn[aria-disabled='true'] {
  opacity: 0.42;
  cursor: not-allowed;
}
.btn-sm {
  --btn-h: 30px;
  padding: 0 10px;
  font-size: var(--t-xs);
}
.btn-icon {
  width: var(--btn-h);
  padding: 0;
}
.btn-quiet {
  background: var(--sheet);
  border-color: var(--rule-strong);
}
.btn-quiet:hover:not(:disabled) {
  background: var(--sheet-2);
  border-color: var(--ink-3);
}
.btn-quiet:active:not(:disabled) {
  background: var(--rule);
}
.btn-primary {
  background: var(--mode-band);
  color: var(--on-band);
  padding: 0 16px;
}
.btn-primary:hover:not(:disabled) {
  background: color-mix(in oklab, var(--mode-band) 84%, #000);
}
.btn-primary:active:not(:disabled) {
  background: color-mix(in oklab, var(--mode-band) 72%, #000);
}
.btn-task {
  background: var(--band-task);
  color: var(--on-band);
  padding: 0 16px;
}
.btn-task:hover {
  background: color-mix(in oklab, var(--band-task) 84%, #000);
}
.btn-danger {
  color: var(--error);
  border-color: var(--error-rule);
}
.btn-danger:hover:not(:disabled) {
  background: var(--error-bg);
  border-color: var(--error);
}

/* ------------------------------------------------------------------ header */

.app-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: stretch;
  gap: var(--s-4);
  height: var(--header-h);
  padding: 0 var(--s-3) 0 var(--s-4);
  background: var(--header);
  color: var(--on-header);
  --brand-turtle: #4cc59c;
}
.app-header :focus-visible {
  outline-color: var(--on-header);
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--on-header);
  text-decoration: none;
  padding-right: var(--s-2);
}
.brand-mark {
  color: var(--on-header);
}
.brand-name {
  font-size: 1.375rem;
  letter-spacing: 0.04em;
}
.nav {
  display: flex;
  align-items: stretch;
}
.nav-link {
  display: flex;
  align-items: center;
  padding: 0 14px;
  color: var(--on-header-2);
  text-decoration: none;
  font-weight: 600;
  font-size: var(--t-sm);
  border-bottom: 3px solid transparent;
  padding-top: 3px;
  transition: color var(--t-fast) var(--ease-out);
}
.nav-link:hover {
  color: var(--on-header);
}
.nav-link[aria-current='page'] {
  color: var(--on-header);
}
.nav-link:nth-child(1)[aria-current='page'] {
  border-bottom-color: #4cc59c;
}
.nav-link:nth-child(2)[aria-current='page'] {
  border-bottom-color: #86b6ec;
}
.nav-link:nth-child(3)[aria-current='page'] {
  border-bottom-color: #e6a669;
}
.nav-link:nth-child(4)[aria-current='page'] {
  border-bottom-color: #cba8e6;
}
.nav-link:focus-visible {
  outline-offset: -4px;
}
.header-tools {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
}
.btn-header {
  color: var(--on-header-2);
}
.btn-header:hover {
  color: var(--on-header);
  background: rgb(255 255 255 / 0.08);
}

/* ------------------------------------------------------------------ studio */

.studio {
  --mode: var(--ink-2d);
  --mode-fill: var(--fill-2d);
  --mode-band: var(--band-2d);
  display: grid;
  grid-template-columns: minmax(400px, 36%) minmax(0, 1fr);
  height: calc(100dvh - var(--header-h));
  min-height: 560px;
}
.studio[data-mode='3d'] {
  --mode: var(--ink-3d);
  --mode-fill: var(--fill-3d);
  --mode-band: var(--band-3d);
}

.studio-code {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  background: var(--sheet);
  border-right: 1px solid var(--rule-strong);
}

.code-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  padding: 10px var(--s-3);
  border-bottom: 1px solid var(--rule);
}

.seg {
  display: inline-flex;
  padding: 2px;
  border: 1px solid var(--rule-strong);
  border-radius: 7px;
  background: var(--sheet-2);
}
.seg-btn {
  min-width: 56px;
  height: 30px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--ink-2);
  font: inherit;
  font-weight: 750;
  font-size: var(--t-sm);
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: background-color var(--t-fast) var(--ease-out), color var(--t-fast) var(--ease-out);
}
.seg-btn:hover:not(:disabled):not([aria-pressed='true']) {
  color: var(--ink);
  background: var(--rule);
}
.seg-btn[aria-pressed='true']:nth-child(1) {
  background: var(--band-2d);
  color: var(--on-band);
}
.seg-btn[aria-pressed='true']:nth-child(2) {
  background: var(--band-3d);
  color: var(--on-band);
}
.seg-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.menu-wrap {
  position: relative;
}
.menu {
  position: absolute;
  right: 0;
  top: calc(100% + 6px);
  z-index: 30;
  min-width: 270px;
  padding: 6px;
  background: var(--sheet);
  border: 1px solid var(--rule-strong);
  border-radius: 8px;
  box-shadow: var(--shadow-pop);
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 10px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: var(--t-sm);
  text-align: left;
  cursor: pointer;
}
.menu-item:hover,
.menu-item:focus-visible {
  background: var(--sheet-2);
}
.menu-item:focus-visible {
  outline-offset: -2px;
}
.menu-item .icon {
  color: var(--ink-3);
}

.runbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: 10px var(--s-3);
  border-bottom: 1px solid var(--rule);
  background: var(--sheet);
}
.tempo {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: var(--t-xs);
  color: var(--ink-2);
}
.tempo label {
  font-weight: 650;
  color: var(--ink);
}
.tempo-out {
  min-width: 9ch;
  font-variant-numeric: tabular-nums;
}
.range {
  width: 108px;
  accent-color: var(--mode-band);
  height: 20px;
  margin: 0;
}

/* ---------------------------------------------------------------- editor */

.editor {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  flex: 1 1 auto;
  min-height: 0;
  background: var(--code-bg);
  font-family: var(--font-code);
  font-size: 14px;
  line-height: 24px;
  font-variant-ligatures: none;
}
.ed-gutter {
  overflow: hidden;
  min-width: 3.4em;
  background: var(--code-gutter);
  border-right: 1px solid var(--rule);
  color: var(--ink-3);
  text-align: right;
  user-select: none;
  font-variant-numeric: tabular-nums;
  font-size: 12.5px;
}
.ed-gutter-inner {
  padding: 12px 10px 12px 12px;
  will-change: transform;
}
.ed-gutter .ln {
  height: 24px;
}
.ed-gutter .ln.is-exec {
  color: var(--ink);
  font-weight: 700;
  background: var(--exec-bg);
  margin: 0 -10px 0 -12px;
  padding: 0 10px 0 12px;
}
.ed-gutter .ln.is-error {
  color: var(--error);
  font-weight: 800;
  background: var(--error-bg);
  margin: 0 -10px 0 -12px;
  padding: 0 10px 0 12px;
}
.ed-main {
  position: relative;
  overflow: hidden;
  min-width: 0;
}
.ed-main:focus-within {
  box-shadow: inset 0 0 0 2px var(--focus);
}
.ed-layer {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}
.ed-hl {
  padding: 12px 14px 48px;
  white-space: pre;
  tab-size: 2;
  color: var(--tok-name);
  width: max-content;
  min-width: 100%;
}
.ed-hl .ln {
  height: 24px;
  margin: 0 -14px;
  padding: 0 14px;
}
.ed-hl .ln.is-exec {
  background: var(--exec-bg);
  box-shadow: inset 0 1px var(--exec-rule), inset 0 -1px var(--exec-rule);
}
.ed-hl .ln.is-error {
  background: var(--error-bg);
}
.ed-probe {
  position: absolute;
  visibility: hidden;
}
.ed-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 12px 14px 48px;
  border: 0;
  outline: none;
  resize: none;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  font: inherit;
  line-height: 24px;
  white-space: pre;
  tab-size: 2;
  overflow: auto;
  font-variant-ligatures: none;
}
.ed-input::selection {
  background: var(--selection);
  color: transparent;
}
.t-cmd {
  color: var(--tok-cmd);
  font-weight: 650;
}
.t-ctl {
  color: var(--tok-ctl);
  font-weight: 750;
}
.t-ma {
  color: var(--tok-ctl);
}
.t-num {
  color: var(--tok-num);
}
.t-proc {
  color: var(--tok-proc);
  font-weight: 650;
}
.t-str {
  color: var(--tok-str);
  text-decoration: underline 3px var(--swatch, transparent);
  text-underline-offset: 5px;
}
.t-comment {
  color: var(--tok-comment);
  font-style: italic;
}
.t-bracket {
  color: var(--tok-bracket);
  font-weight: 800;
}
.t-paren,
.t-op {
  color: var(--tok-op);
}
.t-bad {
  color: var(--error);
}
.t-err {
  text-decoration: wavy underline var(--error) 1.5px;
  text-underline-offset: 4px;
  text-decoration-skip-ink: none;
}
.t-err-eol {
  display: inline-block;
  width: 1ch;
  border-bottom: 2px solid var(--error);
}
.ed-bubble {
  position: absolute;
  z-index: 2;
  max-width: min(46ch, 80%);
  padding: 6px 10px 7px;
  border-radius: 6px;
  background: var(--error-strong);
  color: var(--on-error);
  font-family: var(--font-ui);
  font-size: 13px;
  line-height: 1.35;
  white-space: normal;
  box-shadow: var(--shadow-pop);
}
.ed-bubble::before {
  content: '';
  position: absolute;
  left: 10px;
  top: -5px;
  border: 5px solid transparent;
  border-top: 0;
  border-bottom-color: var(--error-strong);
}

/* ---------------------------------------------------------------- status */

.status {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-height: 64px;
  padding: 11px 14px;
  border-top: 1px solid var(--rule-strong);
  background: var(--sheet);
}
.status > .icon {
  flex: none;
  margin-top: 1px;
}
.status-body {
  min-width: 0;
}
.status-main {
  margin: 0;
  font-weight: 650;
  font-size: var(--t-sm);
}
.status-sub {
  margin: 2px 0 0;
  color: var(--ink-2);
  font-size: var(--t-xs);
}
.status .btn {
  margin-left: auto;
  flex: none;
}
.status.is-error {
  background: var(--error-bg);
}
.status.is-error > .icon {
  color: var(--error);
}
.status.is-error .status-main strong {
  color: var(--error);
}
.status.is-done > .status-body .status-main {
  color: var(--mode);
}

/* ---------------------------------------------------------------- challenge panel */

.task {
  padding: 12px 14px 14px;
  border-bottom: 1px solid var(--rule);
  background: color-mix(in oklab, var(--fill-task) 9%, var(--sheet));
}
.task-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}
.task-title {
  margin: 0;
  font-size: 1.125rem;
  color: var(--ink-task);
}
.task-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: var(--t-xs);
  font-weight: 700;
  color: var(--ok);
}
.task-exit {
  margin-left: auto;
}
.task-text {
  margin: 8px 0 4px;
  max-width: 62ch;
}
.task-req {
  margin: 0 0 4px;
  font-size: var(--t-xs);
  color: var(--ink-2);
}
.task-hint summary {
  cursor: pointer;
  color: var(--ink-task);
  font-weight: 650;
  font-size: var(--t-sm);
  width: fit-content;
}
.task-hint p {
  margin: 4px 0 0;
  font-size: var(--t-sm);
  color: var(--ink-2);
}
.task-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 10px;
}
.check {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: var(--t-sm);
  cursor: pointer;
}
.check input {
  width: 17px;
  height: 17px;
  margin: 0;
  accent-color: var(--band-task);
}
.task-result:empty {
  display: none;
}
.task-result {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
  padding: 8px 10px;
  border-radius: var(--r-ctl);
  font-size: var(--t-sm);
}
.task-result .icon {
  flex: none;
  margin-top: 1px;
}
.task-result.is-pass {
  background: var(--ok-bg);
  color: var(--ink);
}
.task-result.is-pass .icon,
.task-result.is-pass strong {
  color: var(--ok);
}
.task-result.is-fail {
  background: var(--sheet);
  border: 1px solid var(--error-rule);
}
.task-result.is-fail .icon {
  color: var(--error);
}

/* ---------------------------------------------------------------- the chart */

.chart {
  display: grid;
  grid-template-rows: var(--band-h) minmax(0, 1fr) auto;
  min-width: 0;
  min-height: 0;
  background: var(--canvas);
}
.band {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  padding: 0 var(--s-3) 0 var(--s-5);
  background: var(--mode-band);
  color: var(--on-band);
  transition: background-color var(--t-med) var(--ease-out);
}
.band :focus-visible {
  outline-color: var(--on-band);
}
.band-head {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.band .band-title {
  margin: 0;
  font-size: var(--t-2xl);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.band-chip {
  flex: none;
  padding: 3px 7px 2px;
  border: 1.5px solid var(--on-band-2);
  border-radius: 3px;
  font-size: var(--t-xs);
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--on-band-2);
}
.band-tools {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: none;
}
.btn-band {
  color: var(--on-band);
  border-color: rgb(255 255 255 / 0.32);
}
.btn-band:hover {
  background: rgb(255 255 255 / 0.12);
}
.btn-band[aria-pressed='true'] {
  background: rgb(255 255 255 / 0.2);
  border-color: rgb(255 255 255 / 0.6);
}
.btn-band[hidden] {
  display: none;
}

.view-wrap {
  position: relative;
  min-height: 0;
  overflow: hidden;
  background: var(--canvas);
}
.view {
  position: absolute;
  inset: 0;
  touch-action: none;
  cursor: grab;
  outline: none;
}
.view.is-grabbing {
  cursor: grabbing;
}
.view:focus-visible {
  box-shadow: inset 0 0 0 3px var(--focus);
}
.view-canvas,
.view-overlay {
  position: absolute;
  inset: 0;
  display: block;
}
.view-overlay {
  pointer-events: none;
}
.view-notice {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  max-width: 62ch;
  margin: 0;
  padding: 10px 12px;
  background: var(--sheet);
  border: 1px solid var(--rule-strong);
  border-radius: var(--r-ctl);
  font-size: var(--t-sm);
  box-shadow: var(--shadow-pop);
}

.key {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 20px;
  min-height: var(--key-h);
  padding: 9px var(--s-5);
  border-top: 2px solid var(--ink);
  background: var(--sheet);
}
.key-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.key-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: var(--t-xs);
}
.key-n {
  display: inline-grid;
  place-items: center;
  width: 21px;
  height: 21px;
  border: 1.5px solid var(--ink);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.key-swatch {
  width: 22px;
  height: 10px;
  background: var(--swatch);
  border-radius: 2px;
}
.key-text code {
  font-size: 11.5px;
  color: var(--ink-2);
  margin-right: 2px;
}
.key-empty {
  font-size: var(--t-xs);
  color: var(--ink-3);
}
.readout {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: 0 0 0 auto;
  font-family: var(--font-code);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.ro {
  display: inline-flex;
  gap: 5px;
}
.ro-k {
  color: var(--ink-3);
}

/* ---------------------------------------------------------------- pages */

.page-band {
  padding: 32px clamp(16px, 4vw, 48px) 26px;
  background: var(--band-neutral);
  color: var(--on-band);
}
.page-band .band-title {
  margin: 0;
  font-size: var(--t-3xl);
}
.band-lead {
  max-width: 70ch;
  margin: 10px 0 0;
  color: var(--on-band-2);
  font-size: var(--t-md);
}
.band-task {
  background: var(--band-task);
}
.band-ref {
  background: var(--band-ref);
}
.page-body {
  max-width: 1320px;
  padding: 28px clamp(16px, 4vw, 48px) 72px;
}
.page-note {
  margin-top: 28px;
  color: var(--ink-3);
  font-size: var(--t-sm);
}

.cells-section + .cells-section {
  margin-top: 48px;
}
.section-title {
  margin: 0;
  padding-bottom: 8px;
  border-bottom: 2px solid currentColor;
  font-size: var(--t-xl);
  color: var(--ink-2d);
}
.cells-section[data-mode='3d'] .section-title {
  color: var(--ink-3d);
}
.section-lead {
  margin: 8px 0 18px;
  color: var(--ink-2);
}
.cells {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(232px, 1fr));
  gap: 16px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.cell {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--sheet);
  border: 1px solid var(--rule);
  border-radius: 4px;
  color: inherit;
  text-decoration: none;
  transition: border-color var(--t-fast) var(--ease-out), box-shadow var(--t-fast) var(--ease-out);
}
.cell:hover {
  border-color: var(--ink-3);
  box-shadow: 0 4px 14px -6px rgb(20 48 42 / 0.25);
}
.cell:hover .cell-title {
  text-decoration: underline;
  text-underline-offset: 0.2em;
}
.cell-figure {
  display: grid;
  place-items: center;
  aspect-ratio: 240 / 168;
  background: var(--canvas);
  border-bottom: 1px solid var(--rule);
  border-radius: 4px 4px 0 0;
  overflow: hidden;
}
.thumb {
  display: block;
  width: 100%;
  height: auto;
}
.cell-body {
  padding: 12px 14px 14px;
}
.cell-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: var(--t-md);
  font-weight: 720;
}
.cell-n {
  color: var(--ink-task);
  font-variant-numeric: tabular-nums;
}
.cell-text {
  margin: 4px 0 0;
  color: var(--ink-2);
  font-size: var(--t-sm);
}
.cell-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin: 10px 0 0;
  color: var(--ink-3);
  font-size: var(--t-xs);
}
.cell-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 650;
  color: var(--ink-2);
}
.cell-status.is-solved {
  color: var(--ok);
}
.cell-task.is-solved {
  border-color: color-mix(in oklab, var(--ok) 45%, var(--rule));
}
.tag {
  flex: none;
  padding: 2px 6px 1px;
  border-radius: 3px;
  color: var(--on-band);
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.4;
}
.tag-2d {
  background: var(--band-2d);
}
.tag-3d {
  background: var(--band-3d);
}

.tasks-summary {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 18px;
  margin-bottom: 22px;
}
.tasks-count {
  margin: 0;
}
.tasks-count strong {
  font-size: var(--t-lg);
  color: var(--ink-task);
}
.tasks-bar {
  display: flex;
  gap: 4px;
}
.tasks-tick {
  width: 24px;
  height: 8px;
  border-radius: 2px;
  background: var(--rule);
}
.tasks-tick.is-on {
  background: var(--fill-task);
}
.tasks-summary .btn-danger {
  margin-left: auto;
}

/* ---------------------------------------------------------------- reference */

.ref-layout {
  display: grid;
  grid-template-columns: 210px minmax(0, 76ch);
  gap: 48px;
}
.ref-toc {
  position: sticky;
  top: calc(var(--header-h) + 24px);
  align-self: start;
  font-size: var(--t-sm);
}
.ref-toc ol {
  margin: 0;
  padding: 0;
  list-style: none;
  border-left: 2px solid var(--rule);
}
.ref-toc a {
  display: block;
  padding: 5px 0 5px 14px;
  margin-left: -2px;
  border-left: 2px solid transparent;
  color: var(--ink-2);
  text-decoration: none;
}
.ref-toc a:hover {
  color: var(--ink);
  border-left-color: var(--ink-ref);
}
.ref-section + .ref-section {
  margin-top: 52px;
}
.ref-h2 {
  margin: 0 0 14px;
  padding-bottom: 8px;
  border-bottom: 2px solid currentColor;
  font-size: var(--t-xl);
  color: var(--ink-ref);
  scroll-margin-top: calc(var(--header-h) + 16px);
}
.ref-h2:focus {
  outline: none;
}
.ref-p {
  max-width: 70ch;
  margin: 0 0 12px;
}
.ref-p code,
.ref-table code,
.ref-text code {
  padding: 1px 5px;
  background: var(--sheet-2);
  border: 1px solid var(--rule);
  border-radius: 3px;
}
.ref-entry {
  padding: 18px 0 4px;
  border-top: 1px solid var(--rule);
}
.ref-entry:first-of-type {
  border-top: 0;
}
.ref-name {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  margin: 0 0 6px;
  font-weight: 400;
}
.ref-main {
  font-size: 1.0625rem;
  font-weight: 750;
  color: var(--tok-cmd);
}
.ref-alias {
  padding: 1px 6px;
  background: var(--sheet-2);
  border: 1px solid var(--rule);
  border-radius: 3px;
  color: var(--ink-2);
  font-size: 0.8125rem;
}
.ref-arg {
  margin: 0 0 4px;
  font-size: var(--t-sm);
  color: var(--ink-2);
}
.ref-arg-k {
  font-weight: 650;
  color: var(--ink);
}
.ref-text {
  max-width: 70ch;
  margin: 0;
}
.ref-ex {
  margin-top: 16px;
}
.ref-example {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  margin: 12px 0 8px;
  background: var(--code-bg);
  border: 1px solid var(--rule-strong);
  border-radius: 4px;
  overflow: hidden;
}
.ref-code {
  margin: 0;
  padding: 12px 14px;
  overflow-x: auto;
  font-size: 13.5px;
  line-height: 1.65;
}
.ref-fig {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 6px 8px 8px;
  border-left: 1px solid var(--rule);
  background: var(--canvas);
}
.ref-fig .thumb {
  width: 132px;
}
.ref-fig-empty {
  margin: 0;
  max-width: 18ch;
  font-size: var(--t-xs);
  color: var(--ink-3);
}
.table-wrap {
  overflow-x: auto;
  margin: 6px 0 14px;
}
.ref-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--t-sm);
}
.ref-table th,
.ref-table td {
  padding: 8px 10px;
  border-bottom: 1px solid var(--rule);
  text-align: left;
  vertical-align: top;
}
.ref-table thead th {
  border-bottom: 2px solid var(--ink);
  font-weight: 750;
}
.ref-table tbody th {
  font-weight: 600;
}
kbd {
  display: inline-block;
  padding: 1px 6px;
  border: 1px solid var(--rule-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--sheet);
  color: var(--ink);
  font-size: 0.8125rem;
  line-height: 1.5;
  white-space: nowrap;
}

/* ---------------------------------------------------------------- popover & toasts */

.popover {
  position: fixed;
  inset: auto;
  top: calc(var(--header-h) + 8px);
  right: 12px;
  margin: 0;
  width: min(380px, calc(100vw - 24px));
  padding: 16px 18px;
  background: var(--sheet);
  color: var(--ink);
  border: 1px solid var(--rule-strong);
  border-radius: 8px;
  box-shadow: var(--shadow-pop);
}
.popover-title {
  margin: 0;
  font-size: var(--t-md);
  font-weight: 750;
}
.keys-list {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 9px 14px;
  margin: 12px 0 14px;
  font-size: var(--t-sm);
}
.keys-list dd {
  margin: 0;
  color: var(--ink-2);
}
.popover-link {
  font-size: var(--t-sm);
  font-weight: 650;
  color: var(--ink-ref);
}

.toasts {
  position: fixed;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(580px, calc(100vw - 24px));
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 7px 7px 14px;
  background: var(--header);
  color: var(--on-header);
  border-radius: 7px;
  box-shadow: var(--shadow-pop);
  font-size: var(--t-sm);
  pointer-events: auto;
  animation: toast-in var(--t-med) var(--ease-out);
}
.toast.is-leaving {
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 160ms ease-in, transform 160ms ease-in;
}
.toast-msg {
  flex: 1;
  min-width: 0;
}
.toast > .icon {
  flex: none;
  color: #4cc59c;
}
.toast-error > .icon {
  color: #ff8a6e;
}
.toast .btn-quiet {
  background: transparent;
  color: var(--on-header);
  border-color: rgb(255 255 255 / 0.35);
}
.toast .btn-quiet:hover {
  background: rgb(255 255 255 / 0.1);
  border-color: rgb(255 255 255 / 0.6);
}
.toast-close {
  color: var(--on-header-2);
}
.toast-close:hover {
  color: var(--on-header);
  background: rgb(255 255 255 / 0.1);
}
.toast :focus-visible {
  outline-color: var(--on-header);
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

.noscript {
  padding: 24px;
}

/* ---------------------------------------------------------------- responsive */

@media (max-width: 1100px) {
  .studio {
    grid-template-columns: minmax(360px, 42%) minmax(0, 1fr);
  }
  .tempo {
    margin-left: 0;
    flex-basis: 100%;
  }
}

@media (max-width: 860px) {
  .app-header {
    position: static;
    flex-wrap: wrap;
    height: auto;
    padding: 0 var(--s-2) 0 var(--s-3);
    gap: 0;
  }
  .brand {
    height: 48px;
  }
  .nav {
    order: 3;
    flex-basis: 100%;
    margin: 0 calc(-1 * var(--s-2)) 0 calc(-1 * var(--s-3));
    border-top: 1px solid rgb(255 255 255 / 0.1);
  }
  .nav-link {
    flex: 1;
    justify-content: center;
    height: 44px;
    padding: 3px 4px 0;
  }
  .studio {
    display: flex;
    flex-direction: column;
    height: auto;
    min-height: 0;
  }
  .chart {
    order: -1;
    grid-template-rows: auto minmax(300px, 50vh) auto;
  }
  .band {
    min-height: 52px;
    padding: 6px 6px 6px 14px;
  }
  .band .band-title {
    font-size: var(--t-xl);
  }
  .band .btn-label {
    display: none;
  }
  .btn-band {
    width: 36px;
    padding: 0;
  }
  .key {
    padding: 8px 14px;
  }
  .readout {
    margin-left: 0;
  }
  .studio-code {
    border-right: 0;
    border-top: 1px solid var(--rule-strong);
  }
  .runbar {
    position: sticky;
    top: 0;
    z-index: 10;
    box-shadow: 0 1px 0 var(--rule);
  }
  .editor {
    flex: none;
    height: max(300px, 52vh);
  }
  .ref-layout {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
  .ref-toc {
    position: static;
  }
  .ref-toc ol {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    border: 0;
  }
  .ref-toc a {
    margin: 0;
    padding: 4px 10px;
    border: 1px solid var(--rule-strong);
    border-radius: 999px;
    background: var(--sheet);
  }
  .ref-toc a:hover {
    border-color: var(--ink-ref);
  }
}

@media (max-width: 480px) {
  .brand-name {
    font-size: 1.25rem;
  }
  .runbar .btn {
    padding: 0 10px;
  }
  .runbar .btn-primary {
    padding: 0 14px;
  }
  .ref-example {
    grid-template-columns: minmax(0, 1fr);
  }
  .ref-fig {
    flex-direction: row;
    border-left: 0;
    border-top: 1px solid var(--rule);
  }
  .page-band .band-title {
    font-size: var(--t-2xl);
  }
  .cells {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

@media (forced-colors: active) {
  .btn,
  .seg-btn {
    border: 1px solid ButtonText;
  }
  .ed-input {
    color: CanvasText;
  }
  .ed-layer {
    display: none;
  }
}

