input.command:
mkdir -p /tmp/pw && cat > /tmp/pw/serve.ts <<'EOF'
const root = process.argv[2];
const base = process.argv[3] || '/';
const port = Number(process.argv[4] || 4173);
Bun.serve({
  port,
  async fetch(req) {
    const url = new URL(req.url);
    let p = decodeURIComponent(url.pathname);
    if (!p.startsWith(base)) return new Response('not found (outside base)', { status: 404 });
    p = p.slice(base.length);
    if (p === '' || p.endsWith('/')) p += 'index.html';
    const f = Bun.file(`${root}/${p}`);
    if (!(await f.exists())) return new Response('not found', { status: 404 });
    return new Response(f);
  },
});
console.log('serving', root, 'at', base, port);
EOF
