input.command:
cat > /tmp/pw/shots.ts <<'EOF'
import { chromium } from 'playwright';
const BASE = 'http://localhost:4173/Logomocja/builds/x/';
const out = process.argv[2] || '/tmp/pw/out';
await Bun.$`mkdir -p ${out}`;
const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const errors: string[] = [];
async function page(w: number, h: number, scheme: 'light' | 'dark' = 'light') {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, colorScheme: scheme, deviceScaleFactor: 1 });
  const p = await ctx.newPage();
  p.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`${m.type()}: ${m.text()}`); });
  p.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  return p;
}
const shots = (process.argv[3] || 'all').split(',');
const want = (k: string) => shots.includes('all') || shots.includes(k);

if (want('desk')) {
  const p = await page(1440, 900);
  await p.goto(BASE);
  await p.waitForTimeout(800);
  await p.screenshot({ path: `${out}/studio-2d.png` });
  const r = await p.evaluate(() => window.logomocja.open(`; Rekurencja: gałąź rysuje dwie mniejsze gałęzie.
oto gałąź ma: dł
  jeśli dł < 6 [stop]
  jeżeli dł > 30 [kolor "#6b4f2a" grubosc 3] [kolor "#2f8f4e" grubosc 1]
  np dł
  lw 25
  gałąź dł * 0.7
  pw 50
  gałąź dł * 0.7
  lw 25
  pod ws dł opu
już

pod ws 120 opu
gałąź 90`, '2d'));
  console.log('open drzewo', r.segments.length, r.error);
  await p.waitForTimeout(300);
  await p.screenshot({ path: `${out}/studio-drzewo.png` });
  const r2 = await p.evaluate(() => window.logomocja.open('powtorz 4 [np 100 pw 90]\nnp 10 -5\n', '2d'));
  console.log('err', JSON.stringify(r2.error));
  await p.waitForTimeout(200);
  await p.screenshot({ path: `${out}/studio-error.png` });
  const r3 = await p.evaluate(() => window.logomocja.open(`; Drzewo w przestrzeni: gałęzie obracają się wokół pnia.
oto gałąź ma: dł
  jeśli dł < 8 [stop]
  jeżeli dł > 30 [kolor "#6b4f2a" grubosc 3] [kolor "#2f8f4e" grubosc 1]
  np dł
  powtorz 3 [
    gora 35
    gałąź dł * 0.6
    dol 35
    pp 120
  ]
  pod ws dł opu
już

gora 90
gałąź 70`, '3d'));
  console.log('open drzewo3d', r3.segments.length, r3.error);
  await p.waitForTimeout(500);
  await p.screenshot({ path: `${out}/studio-3d.png` });
  await p.goto(BASE + '#/przyklady'); await p.waitForTimeout(500);
  await p.screenshot({ path: `${out}/gallery.png`, fullPage: true });
  await p.goto(BASE + '#/zadania'); await p.waitForTimeout(400);
  await p.screenshot({ path: `${out}/tasks.png`, fullPage: true });
  await p.goto(BASE + '#/zadanie/trojkat'); await p.waitForTimeout(600);
  await p.screenshot({ path: `${out}/task-trojkat.png` });
  await p.goto(BASE + '#/pomoc'); await p.waitForTimeout(400);
  await p.screenshot({ path: `${out}/ref.png` });
}
if (want('dark')) {
  const p = await page(1440, 900, 'dark');
  await p.goto(BASE); await p.waitForTimeout(800);
  await p.evaluate(() => window.logomocja.open(`; Każdy bok jest dłuższy od poprzedniego, kolory na zmianę.
grubosc 2
niech zmiana 1
powtorz 90 [
  jeżeli zmiana > 0 [kolor "#16866a"] [kolor "#c1763d"]
  niech zmiana -zmiana
  np nrpowt * 2.5
  pw 89
]`, '2d'));
  await p.waitForTimeout(300);
  await p.screenshot({ path: `${out}/dark-studio.png` });
  await p.evaluate(() => window.logomocja.open('kolor "#a478c0"\ngrubosc 3\ngora 30\npowtorz 36 [np 12 pw 10]', '3d'));
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${out}/dark-3d.png` });
  await p.goto(BASE + '#/przyklady'); await p.waitForTimeout(400);
  await p.screenshot({ path: `${out}/dark-gallery.png` });
}
if (want('mobile')) {
  const p = await page(390, 844);
  await p.goto(BASE); await p.waitForTimeout(800);
  await p.screenshot({ path: `${out}/mobile-studio.png`, fullPage: true });
  await p.goto(BASE + '#/zadanie/kwiat'); await p.waitForTimeout(600);
  await p.screenshot({ path: `${out}/mobile-task.png`, fullPage: true });
  await p.goto(BASE + '#/pomoc'); await p.waitForTimeout(400);
  await p.screenshot({ path: `${out}/mobile-ref.png` });
}
console.log(errors.join('\n') || 'no console errors');
await browser.close();
EOF
