import { chromium } from 'playwright';
const BASE = 'http://localhost:4173/Logomocja/builds/x/';
const out = process.argv[2];
const browser = await chromium.launch({ args: ['--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const errors: string[] = [];
async function newPage(w: number, h: number, scheme: 'light' | 'dark' = 'light') {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, colorScheme: scheme });
  const p = await ctx.newPage();
  p.on('pageerror', (e) => errors.push(e.message));
  p.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
  await p.addInitScript(() => document.documentElement.style.setProperty('--t-med', '0ms'));
  return p;
}
const tree = `; Rekurencja: gałąź rysuje dwie mniejsze gałęzie.
oto gałąź ma: dł
  jeśli dł < 6 [stop]
  jeżeli dł > 30 [kolor "#6b4f2a" grubosc 3] [kolor "#2f8f4e" grubosc 1]
  np dł
  lw 25
  gałąź dł * 0.7
  pw 50
  gałąź dł * 0.7
  lw 25
  pod ws dł opu
już

pod ws 120 opu
gałąź 90`;
// desktop: studio with a standard program
let p = await newPage(1440, 900);
await p.goto(BASE); await p.waitForTimeout(700);
await p.evaluate((s) => window.logomocja.open(s, '2d'), tree); await p.waitForTimeout(400);
await p.screenshot({ path: `${out}/desktop.png`, fullPage: true });
await p.evaluate(() => window.logomocja.open('oto kwadrat ma: bok\n  powtorz 4 [np bok pw 90]\njuż\nkolor "#c1763d"\nkwadrat 80\nnp 10 -5\n', '2d')); await p.waitForTimeout(300);
await p.screenshot({ path: `${out}/desktop-error.png` });
await p.evaluate(() => window.logomocja.open('; Dwanaście okręgów, każdy przechylony o 15 stopni.\ngrubosc 2\nniech zmiana 1\npowtorz 12 [\n  jeżeli zmiana > 0 [kolor "#16866a"] [kolor "#2b6fb3"]\n  niech zmiana -zmiana\n  powtorz 36 [np 10 gora 10]\n  pp 15\n]', '3d')); await p.waitForTimeout(600);
await p.screenshot({ path: `${out}/desktop-3d.png` });
await p.goto(BASE + '#/zadanie/szesciokat'); await p.waitForTimeout(700);
await p.getByRole('button', { name: 'Sprawdź' }).click(); await p.waitForTimeout(300);
await p.screenshot({ path: `${out}/desktop-task.png` });
await p.goto(BASE + '#/przyklady'); await p.waitForTimeout(500);
await p.screenshot({ path: `${out}/desktop-examples.png`, fullPage: true });
await p.goto(BASE + '#/zadania'); await p.waitForTimeout(400);
await p.screenshot({ path: `${out}/desktop-tasks.png`, fullPage: true });
await p.goto(BASE + '#/pomoc'); await p.waitForTimeout(400);
await p.screenshot({ path: `${out}/desktop-reference.png` });
// dark
p = await newPage(1440, 900, 'dark');
await p.goto(BASE); await p.waitForTimeout(700);
await p.evaluate((s) => window.logomocja.open(s, '2d'), tree); await p.waitForTimeout(300);
await p.screenshot({ path: `${out}/desktop-dark.png` });
// mobile
p = await newPage(390, 844);
await p.goto(BASE); await p.waitForTimeout(700);
await p.evaluate((s) => window.logomocja.open(s, '2d'), tree); await p.waitForTimeout(400);
await p.screenshot({ path: `${out}/mobile.png`, fullPage: true });
await p.goto(BASE + '#/zadanie/kwiat'); await p.waitForTimeout(700);
await p.screenshot({ path: `${out}/mobile-task.png`, fullPage: true });
await p.goto(BASE + '#/przyklady'); await p.waitForTimeout(500);
await p.screenshot({ path: `${out}/mobile-examples.png` });
const sw = await p.evaluate(() => document.documentElement.scrollWidth);
console.log('mobile scrollWidth', sw);
console.log('errors', errors.length ? errors : 'none');
await browser.close();
EOF
